    /// A `ViT` of timm's defaults with 1000 classes: `image_size` pixel
    /// images in `patch_size` patches, `depth` layers `embed_dim` wide of
    /// `num_heads` heads.
    fn vit(
        image_size: usize,
        patch_size: usize,
        embed_dim: usize,
        depth: usize,
        num_heads: usize,
    ) -> Self {
        Self::new(image_size, patch_size, embed_dim, depth, num_heads, 1000)
    }

