#[cfg(test)]
mod tests {
    use super::*;
    use crate::burner::module::ToStructureConfig;

    /// Every prefab lowers, at its name's size where the name ends in one.
    #[test]
    fn test_prefabs_lower() {
        for name in ViTContractConfig::prefab_names() {
            let config = ViTContractConfig::expect_prefab(name);
            config
                .try_to_structure()
                .unwrap_or_else(|e| panic!("{name}: {e}"));
            let last = name.trim_end_matches("_miil").rsplit('_').next().unwrap();
            if let Ok(size) = last.parse::<usize>() {
                assert_eq!(config.image_size, size, "{name}");
            }
        }
        assert_eq!(ViTContractConfig::prefab_names().len(), 132);
    }
}
